<?php session_start();require 'config.php';if(!isset($_SESSION['user_id'])){header('Location:login.php');exit;}$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT * FROM courses WHERE id=?');$s->bind_param('i',$id);$s->execute();$c=$s->get_result()->fetch_assoc();if(!$c)die('دوره پیدا نشد');if($_SERVER['REQUEST_METHOD']==='POST'){$u=$_SESSION['user_id'];$p=$conn->prepare("INSERT INTO purchases(user_id,course_id) VALUES(?,?)");$p->bind_param('ii',$u,$id);$p->execute();header('Location:success.php?id='.$id);exit;}?><!doctype html><html lang='fa' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>پرداخت آزمایشی</title><link rel='stylesheet' href='style.css'></head><body><main class='formbox'><h1>💳 پرداخت آزمایشی</h1><h2><?=htmlspecialchars($c['title'])?></h2><p>مبلغ: <b><?=number_format($c['price'])?> تومان</b></p><p>این صفحه شبیه‌ساز پرداخت است و هیچ پول واقعی دریافت نمی‌کند.</p><form method='post'><button class='btn'>تأیید پرداخت آزمایشی</button></form><a href='courses.php'>بازگشت</a></main></body></html>